## Description

I get the error: '**Field `embedding` should be a string or a string array.**' when I try to use semantic search. Collection has embeddings auto generated as from the example in the docs and the embeddings field is defined as float[].


**Collection**
```use Typesense\Client;

$clientConfig = [
    "api_key" => "12345",
    "nodes" => [
        [
            "host" => "localhost",
            "port" => "8108",
            "protocol" => "http"
        ]
    ],
    "connection_timeout_seconds" => 2
];

$client = new Client($clientConfig);

$schema = [
    "name" => "products",
    "fields" => [
        [
            "name" => "id",
            "type" => "string"
        ],
        [
            "name" => "name",
            "type" => "string"
        ],
        [
            "name" => "brand",
            "type" => "string",
            "optional" => true
        ],
        [
            "name" => "category",
            "type" => "string"
        ],
        [
            "name" => "description",
            "type" => "string"
        ],
        [
            "name" => "embedding",
            "type" => "float[]",
            "embed" => [
                "from" => [
                    //   "brand",
                    "name",
                    "category",
                    "description"
                ],
                "model_config" => [
                    "model_name" => "ts/all-MiniLM-L12-v2"
                ]
            ]
        ]
    ]
];

$client->collections->create($schema);
```

**Query**

```use Typesense\Client;

$clientConfig = [
    "api_key" => "12345",
    "nodes" => [
        [
            "host" => "localhost",
            "port" => "8108",
            "protocol" => "http"
        ]
    ],
    "connection_timeout_seconds" => 2
];

$client = new Client($clientConfig);

$searchRequests = [
    "searches" => [
        [
            "collection" => "products",
            "q" => "iphone",
            "query_by" => "embedding"
        ]
    ]
];

$commonSearchParams = [];
$client->multiSearch->perform($searchRequests, $commonSearchParams);
```


## Metadata

0.25.0

